];

function sign(list){
var sb='';
sb+="Fb0gqLMSf5Android";
list=list.sort();
i=0;
while(i<list.length){
if(i==0){
sb+=list[i]
}else{
    if(list[i].match(/lang-app=/)){  
      i2=i+1;
     i3=i2+1;
     if (list[i2] != null && list[i2].match(/lang=/)) {
                        sb+="&";
                        sb+=list[i2];

                        sb+="&";
                        sb+=list[i];

                        i = i3;
                    }
           }
                sb+="&";
                sb+=list[i];             
      }
i++
}
sb+="AEdDtho2CjiH901aVK7swFqclu6NmzJ4";
return String(java.md5Encode(sb)).toUpperCase()
}

sign=sign(list);

json={"sign":sign,"packageName":"com.lestory.jihua.an","time":time,"token":"","locale":"CN","osType":"2","book_id":result,"lang":"zh-hans","lang-app":"zh-Hans","ver":"2.1.3","product":1,"sysVer":"10"}
